mixed-shared-group-key-filter.specification:
schema_version: '1.0'
domain: TEST
keys: [ID, SECTION, SEQ]
input: {SRC: {path: input.csv, types: {SEQ: int}}}
output: {path: result.csv, columns: [ID, SECTION, SEQ, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: SECTION, type: str}
  - {name: SEQ, type: int}
  - {name: VALUE, type: str, derivation: {case: [{when: 'TRUE', then: {source: {variable: SRC.ID, filter: 'SRC.SEQ > 0'}}}, {otherwise: {literal: unused}}]}}
rows:
  - {id: grouped, dataset: SRC, group_by: [SRC.ID], derivations: {SECTION: {literal: grouped}, SEQ: {literal: 0}}}
  - {id: records, dataset: SRC, derivations: {SECTION: {literal: record}, SEQ: SRC.SEQ}}

mixed-group-key-keep.specification:
schema_version: '1.0'
domain: TEST
keys: [ID, SECTION, SEQ]
input: {SRC: {path: input.csv, types: {SEQ: int}}}
output: {path: result.csv, columns: [ID, SECTION, SEQ, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: SECTION, type: str}
  - {name: SEQ, type: int}
  - {name: VALUE, type: str, derivation: {source: {variable: SRC.ID, order_by: [SRC.SEQ], keep: last}}}
rows:
  - {id: grouped, dataset: SRC, group_by: [SRC.ID], derivations: {SECTION: {literal: grouped}, SEQ: {literal: 0}}}
  - {id: records, dataset: SRC, derivations: {SECTION: {literal: record}, SEQ: SRC.SEQ}}

